import { useState } from "react"
type YarnWeightInput = {
  label: string,
  options: string[]
}[]

type FiberListInput = {
  label: string,
  value: string
}[]

const types:YarnWeightInput = [
  {
    label: "Lace",
    options: ["Crochet Thread", "Fingering"]
  },
  {
    label: "Super Fine",
    options: ["Sock", "Fingering", "Baby"]
  },
  {
    label: "Fine",
    options: ["Baby", "Sport"]             
  },
  {
    label: "Light",
    options: ["DK", "Light Worsted"]
  },
  {
    label: "Medium",
    options: ["Worsted", "Afghan", "Aran"]
  },
  {
    label: "Bulky",
    options: ["Chunky", "Craft", "Rug"]
  },
  {
    label: "Super Bulky",
    options: ["Super Bulky", "Roving"]
  },
  {
    label: "Jumbo",
    options: ["Jumbo", "Roving"]
  }
]

const fiberList:FiberListInput = [
  {
    label: "Wool",
    value: "wool",
  },
  {
    label: "Alpaca",
    value: "alpaca"
  },
  {
    label: "Camel",
    value: "Camel"
  }
]

export default function Filter() {
  return (
    <form>
      <fieldset>
        <legend>
          Search by part or whole name
        </legend>
        <label htmlFor="search-name">Name</label>
        <input id="search-name" name="name" type="text" />
      </fieldset>
      <fieldset>
        <legend>
          Yarn Weight
        </legend>
        {types.map((type, index) => {
          return (
            <div key={type.label} className="search--field-sub">
              <strong>{index} - {type.label}</strong>
              {type.options.map(opt => {
                const slug = opt.split(" ").join("_").toLowerCase();
                const id = `search-weight--${index}-${slug}`;
                return (
                  <div key={(type.label + slug)}>
                  <input id={id} name={`weight[${index}][${slug}]`} type="checkbox"/>
                  <label htmlFor={id}>{opt}</label>
                  </div>
                );
              })}
            </div>
          );
        })}
      </fieldset>
      <fieldset>
        <legend>
          Fibers
        </legend>
        <div className="search--field-sub">
          <label htmlFor="fibers[wool][percentage]">Wool</label>
          <input type="range" id="fibers[wool][percentage]" value={50} name="fibers-wool-percetage" min="0" max="100" />
        </div>
        <div className="search--field-sub">
          <label htmlFor="fibers[alpaca][percentage]">Alpaca</label>
          <input type="range" id="fibers[alpaca][percentage]" value={50} name="fibers-alpaca-percetage" min="0" max="100" />
        </div>
        <select>
          {fiberList.map(fiber => {
            return (
             <option key={fiber.value}>{fiber.label}</option>
           )
          })}
        </select>
        <button type="button">Add Another Fiber</button>
      </fieldset>
    </form>
  )
}
